  "content": "// Exercise page module
// Registers the Exercise page with the shared ForgeAI shell
// Expected globals: window.ForgeAI, ctx.root, ctx.api, ctx.search

(function () {
  // Register the page under the slug "exercise"
  window.ForgeAI.registerPage('exercise', async function (ctx) {
    const { root, api } = ctx;
    // Clear any existing content
    root.innerHTML = '';

    // Helper to create elements with classes and text
    function el(tag, className, text) {
      const node = document.createElement(tag);
      if (className) node.className = className;
      if (text !== undefined) node.textContent = text;
      return node;
    }

    // ----- UI Construction -----
    const container = el('div', 'exercise-page');
    const header = el('div', 'exercise-header');
    const title = el('h2', 'page-title', 'Exercises');
    const addBtn = el('button', 'btn btn-primary', 'Add Exercise');
    addBtn.addEventListener('click', openAddModal);
    header.appendChild(title);
    header.appendChild(addBtn);
    container.appendChild(header);

    const tableWrapper = el('div', 'exercise-table-wrapper');
    container.appendChild(tableWrapper);

    root.appendChild(container);

    // ----- Data fetching -----
    async function loadExercises() {
      tableWrapper.innerHTML = '<p>Loading…</p>';
      try {
        const resp = await api('/api/exercises'); // GET by default
        if (!resp.success) throw new Error('API error');
        const exercises = resp.data;
        renderTable(exercises);
      } catch (e) {
        console.error(e);
        tableWrapper.innerHTML = '<p class="error">Failed to load exercises.</p>';
      }
    }

    // ----- Table rendering -----
    function renderTable(data) {
      if (!data || data.length === 0) {
        tableWrapper.innerHTML = '<p class="empty-state">No exercises have been added yet.</p>';
        return;
      }

      const table = el('table', 'exercise-table');
      const thead = el('thead');
      const headerRow = el('tr');
      ['Name', 'Muscle Group', 'Equipment', 'Actions'].forEach(txt => {
        const th = el('th', null, txt);
        headerRow.appendChild(th);
      });
      thead.appendChild(headerRow);
      table.appendChild(thead);

      const tbody = el('tbody');
      data.forEach(item => {
        const tr = el('tr');
        tr.appendChild(el('td', null, item.name || '-'));
        tr.appendChild(el('td', null, item.muscle_group || '-'));
        tr.appendChild(el('td', null, item.equipment || '-'));
        const actionTd = el('td');
        const viewBtn = el('button', 'btn btn-sm btn-secondary', 'View');
        viewBtn.addEventListener('click', () => openViewModal(item.id));
        actionTd.appendChild(viewBtn);
        tr.appendChild(actionTd);
        tbody.appendChild(tr);
      });
      table.appendChild(tbody);
      tableWrapper.innerHTML = '';
      tableWrapper.appendChild(table);
    }

    // ----- Add Exercise Modal -----
    function openAddModal() {
      const overlay = el('div', 'modal-overlay');
      const modal = el('div', 'modal');
      const header = el('h3', null, 'Add New Exercise');
      const form = el('form');

      const fields = [
        { name: 'name', label: 'Exercise Name', type: 'text' },
        { name: 'muscle_group', label: 'Muscle Group', type: 'text' },
        { name: 'equipment', label: 'Equipment', type: 'text' }
      ];

      fields.forEach(f => {
        const wrapper = el('div', 'form-group');
        const label = el('label', null, f.label);
        label.htmlFor = f.name;
        const input = el('input');
        input.type = f.type;
        input.id = f.name;
        input.name = f.name;
        input.required = true;
        wrapper.appendChild(label);
        wrapper.appendChild(input);
        form.appendChild(wrapper);
      });

      const submitBtn = el('button', 'btn btn-primary', 'Create');
      submitBtn.type = 'submit';
      const cancelBtn = el('button', 'btn btn-secondary', 'Cancel');
      cancelBtn.type = 'button';
      cancelBtn.addEventListener('click', () => document.body.removeChild(overlay));

      form.appendChild(submitBtn);
      form.appendChild(cancelBtn);

      form.addEventListener('submit', async function (e) {
        e.preventDefault();
        const formData = new FormData(form);
        const payload = {
          id: '', // backend generates id
          name: formData.get('name'),
          muscle_group: formData.get('muscle_group'),
          equipment: formData.get('equipment')
        };
        try {
          const resp = await api('/api/exercises', { method: 'POST', json: payload });
          if (resp.success) {
            alert('Exercise created successfully');
            document.body.removeChild(overlay);
            loadExercises();
          } else {
            throw new Error('Creation failed');
          }
        } catch (err) {
          console.error(err);
          alert('Error creating exercise');
        }
      });

      modal.appendChild(header);
      modal.appendChild(form);
      overlay.appendChild(modal);
      document.body.appendChild(overlay);
    }

    // ----- View Exercise Modal -----
    async function openViewModal(id) {
      const overlay = el('div', 'modal-overlay');
      const modal = el('div', 'modal');
      const header = el('h3', null, 'Exercise Details');
      const content = el('div', 'modal-content', 'Loading…');

      modal.appendChild(header);
      modal.appendChild(content);
      const closeBtn = el('button', 'btn btn-secondary', 'Close');
      closeBtn.addEventListener('click', () => document.body.removeChild(overlay));
      modal.appendChild(closeBtn);
      overlay.appendChild(modal);
      document.body.appendChild(overlay);

      try {
        const resp = await api(`/api/exercises/${id}`);
        if (!resp.success) throw new Error('API error');
        const ex = resp.data;
        content.innerHTML = `
          <p><strong>Name:</strong> ${ex.name || '-'}</p>
          <p><strong>Muscle Group:</strong> ${ex.muscle_group || '-'}</p>
          <p><strong>Equipment:</strong> ${ex.equipment || '-'}</p>
        `;
      } catch (e) {
        console.error(e);
        content.textContent = 'Failed to load details.';
      }
    }

    // Initial load
    loadExercises();
  });
})();
"
}
